/* global BigInt */
import React, { useCallback, useEffect, useRef, useState } from "react";
import { formatUnits, isAddress } from "viem";
import { quiz_address } from "../../../contract/config";
import { persistRewardPayoutEntriesToServer, syncRewardPayoutLedgerFromServer } from "../../../utils/rewardPayoutLedger";

const normalizeAnswer = (value) => String(value || "").trim().replace(/[０-９]/g, (char) => String(char.charCodeAt(0) - "０".charCodeAt(0)));

export default function Reward_recovery_panel({ cont, quizzes = [], students = [], onRecovered, selectedQuizKey = "", onSelectedQuizChange }) {
    const [rows, setRows] = useState([]);
    const [selected, setSelected] = useState([]);
    const [approvedCorrections, setApprovedCorrections] = useState([]);
    const [activeQuizKey, setActiveQuizKey] = useState("");
    const [busy, setBusy] = useState(false);
    const [loading, setLoading] = useState(true);
    const [message, setMessage] = useState("");
    const [results, setResults] = useState([]);
    const [extraAddress, setExtraAddress] = useState("");
    const [extraStudents, setExtraStudents] = useState([]);
    const loadVersion = useRef(0);
    const quizKey = JSON.stringify(quizzes.map((quiz) => ({ id: quiz.quizId, source: quiz.sourceAddress || quiz_address, title: quiz.title })));
    const studentList = [...students.map((student) => typeof student === "string" ? { address: student } : { address: student.address, name: student.name }), ...extraStudents];
    const studentKey = JSON.stringify(studentList.filter((student, index) => studentList.findIndex((other) => other.address.toLowerCase() === student.address.toLowerCase()) === index));
    useEffect(() => { setActiveQuizKey(selectedQuizKey); }, [selectedQuizKey]);

    const load = useCallback(async () => {
        const version = ++loadVersion.current;
        setLoading(true);
        try {
            if (!JSON.parse(quizKey).length) { setRows([]); return []; }
            await syncRewardPayoutLedgerFromServer();
            const candidates = [];
            for (const quiz of JSON.parse(quizKey)) {
                if (activeQuizKey && `${quiz.source}:${quiz.id}` !== activeQuizKey) continue;
                const simple = await cont.get_quiz_simple_uncached(quiz.id, quiz.source);
                const deadline = Number(simple?.[6] || 0);
                if (!deadline || Date.now() / 1000 <= deadline) continue;
                const [finalized, answer] = await Promise.all([
                    cont.get_is_payment(quiz.id, quiz.source),
                    cont.get_revealed_correct_answer(quiz.id, quiz.source),
                ]);
                const reward = BigInt(simple?.[7] || 0);
                if (reward <= 0n) continue;
                const studentBatch = JSON.parse(studentKey);
                for (let start = 0; start < studentBatch.length; start += 10) {
                    const batch = await Promise.all(studentBatch.slice(start, start + 10).map(async (student) => {
                    const detail = await cont.get_student_answer_detail(student.address, quiz.id, quiz.source, { strict: true });
                    if (!detail || detail.readError) throw new Error("回答の取得に失敗しました。再読み込みしてください。");
                    if (!detail.submitted || (detail.state === 3 && !finalized)) return null;
                    const correct = detail.state === 2 || (answer && normalizeAnswer(answer) === normalizeAnswer(detail.answerText));
                    if (!correct && !finalized) return null;
                    const paid = await cont.get_verified_quiz_paid_wei(student.address, quiz.id, quiz.source, detail);
                    if (paid >= reward) return null;
                    const recovered = await cont.get_recovery_paid_wei(student.address, quiz.id, quiz.source);
                    const missing = reward - paid - recovered;
                    if (missing <= 0n) return null;
                    return { ...student, ...quiz, key: `${quiz.source}:${quiz.id}:${student.address}`, amount: missing.toString(), answerText: detail.answerText, correctAnswer: answer, requiresReview: !correct };
                    }));
                    candidates.push(...batch.filter(Boolean));
                }
            }
            if (version !== loadVersion.current) return null;
            setRows(candidates);
            setSelected((current) => current.filter((key) => candidates.some((row) => row.key === key)));
            setApprovedCorrections((current) => current.filter((key) => candidates.some((row) => row.key === key && row.requiresReview)));
            return candidates;
        } catch (error) {
            if (version !== loadVersion.current) return null;
            setRows([]);
            setSelected([]);
            setApprovedCorrections([]);
            setMessage(`未配布報酬の確認に失敗しました: ${error.shortMessage || error.message}`);
            return null;
        } finally {
            if (version === loadVersion.current) setLoading(false);
        }
    }, [cont, quizKey, studentKey, activeQuizKey]);

    useEffect(() => { load(); return () => { loadVersion.current += 1; }; }, [load]);

    async function execute() {
        setBusy(true);
        setMessage("");
        try {
            const latest = await load();
            if (!latest) return;
            const targets = latest.filter((row) => selected.includes(row.key) && (!row.requiresReview || approvedCorrections.includes(row.key)));
            if (!targets.length) { setMessage("選択した学生に未配布の報酬はありません。"); return; }
            const total = targets.reduce((sum, row) => sum + BigInt(row.amount), 0n);
            const confirmation = [
                `教員ウォレットから ${targets.length} 件、合計 ${formatUnits(total, 18)} TFT を追加送金します。`,
                ...targets.map((row) => `#${row.id} ${row.title} / ${row.name || row.address} / 回答: ${row.answerText} / ${row.requiresReview ? "教員確認により正解へ訂正 / " : ""}${formatUnits(BigInt(row.amount), 18)} TFT`),
                "この内容で配布しますか？",
            ].join("\n");
            if (!window.confirm(confirmation)) return;
            const nextResults = [];
            for (const row of targets) {
                try {
                    const result = await cont.recover_quiz_reward(row.id, row.address, row.source, row.amount, row.requiresReview);
                    let recordError = false;
                    try {
                        await persistRewardPayoutEntriesToServer([{
                            quizId: row.id, sourceAddress: row.source, quizTitle: row.title,
                            studentAddress: row.address, studentName: row.name || "", answerText: row.answerText,
                            resultState: "correct", rewardWei: result.rewardWei,
                            rewardTft: Number(formatUnits(BigInt(result.rewardWei), 18)),
                            txHash: result.hash, mode: row.requiresReview ? "recovery_manual" : "recovery", actorAddress: result.actorAddress,
                            confirmed: true, paidAt: new Date().toISOString(),
                        }]);
                    } catch (_) { recordError = true; }
                    nextResults.push({ ...row, hash: result.hash, text: recordError ? "送金成功（履歴の同期待ち）" : "送金成功" });
                } catch (error) {
                    nextResults.push({ ...row, text: `未完了: ${error.shortMessage || error.message}` });
                    setResults([...nextResults]);
                    break;
                }
                setResults([...nextResults]);
            }
            await load();
            if (onRecovered) await onRecovered();
        } finally { setBusy(false); }
    }

    return (
        <section id="reward-recovery-panel" style={{ marginTop: 24, scrollMarginTop: 90 }} aria-label="未配布報酬の追加配布">
            <h3>未配布報酬の追加配布</h3>
            <select className="form-control" style={{ width: "100%", maxWidth: "100%", marginBottom: 12 }} aria-label="追加配布を確認する問題" value={activeQuizKey} disabled={busy} onChange={(event) => { setSelected([]); setApprovedCorrections([]); setActiveQuizKey(event.target.value); onSelectedQuizChange?.(event.target.value); }}>
                <option value="">すべての問題</option>
                {JSON.parse(quizKey).map((quiz) => <option key={`${quiz.source}:${quiz.id}`} value={`${quiz.source}:${quiz.id}`}>#{quiz.id} {quiz.title}</option>)}
            </select>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 12, alignItems: "center", marginBottom: 12 }}>
                <span>{loading ? "送金履歴を確認中..." : `未配布 ${rows.filter((row) => !row.requiresReview).length} 件`}</span>
                {!loading && rows.some((row) => row.requiresReview) && <span>採点確認 {rows.filter((row) => row.requiresReview).length} 件</span>}
                <button type="button" className="btn-action" disabled={busy || loading} onClick={() => { setMessage(""); load(); }}>未配布を再確認</button>
                <button type="button" className="btn-action" disabled={busy || loading || !selected.length} onClick={execute}>選択した学生に追加配布</button>
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 12 }}>
                <input aria-label="学生ウォレットを追加" className="form-control" style={{ flex: "1 1 280px", minWidth: 0 }} placeholder="学生のウォレットアドレス" value={extraAddress} disabled={busy} onChange={(event) => setExtraAddress(event.target.value)} />
                <button type="button" className="btn-action" disabled={busy || loading || !isAddress(extraAddress.trim())} onClick={() => { setExtraStudents((current) => [...current, { address: extraAddress.trim() }]); setExtraAddress(""); }}>確認対象に追加</button>
            </div>
            {message && <p role="alert">{message}</p>}
            {!loading && rows.length > 0 && (
                <div style={{ overflowX: "auto" }}>
                    <table className="results-table" style={{ width: "100%", minWidth: 820 }}>
                        <thead><tr><th>選択</th><th>問題</th><th>学生</th><th>回答</th><th>登録正解</th><th>判定</th><th>追加配布額</th></tr></thead>
                        <tbody>{rows.map((row) => (
                            <tr key={row.key}>
                                <td><input type="checkbox" aria-label={`追加配布 #${row.id} ${row.name || row.address}`} disabled={busy || (row.requiresReview && !approvedCorrections.includes(row.key))} checked={selected.includes(row.key)} onChange={() => setSelected((current) => current.includes(row.key) ? current.filter((key) => key !== row.key) : [...current, row.key])} /></td>
                                <td>#{row.id} {row.title}</td>
                                <td style={{ overflowWrap: "anywhere" }}>{row.name || row.address}</td>
                                <td style={{ overflowWrap: "anywhere" }}>{row.answerText || "-"}</td>
                                <td style={{ overflowWrap: "anywhere" }}>{row.correctAnswer || "-"}</td>
                                <td>{row.requiresReview ? (
                                    <label style={{ whiteSpace: "nowrap" }}><input type="checkbox" aria-label={`正解に訂正 #${row.id} ${row.name || row.address}`} disabled={busy} checked={approvedCorrections.includes(row.key)} onChange={(event) => {
                                        const approved = event.target.checked;
                                        setApprovedCorrections((current) => approved ? [...current, row.key] : current.filter((key) => key !== row.key));
                                        setSelected((current) => approved ? Array.from(new Set([...current, row.key])) : current.filter((key) => key !== row.key));
                                    }} /> 正解に訂正</label>
                                ) : "正解"}</td>
                                <td>{formatUnits(BigInt(row.amount), 18)} TFT</td>
                            </tr>
                        ))}</tbody>
                    </table>
                </div>
            )}
            {results.map((row) => <p key={row.key} role="status">#{row.id} {row.name || row.address}: {row.text}{row.hash && <> <a href={`https://amoy.polygonscan.com/tx/${row.hash}`} target="_blank" rel="noreferrer">送金履歴</a></>}</p>)}
        </section>
    );
}
